{
  "flashcards": [
    {
      "front": "What is the primary goal of query tuning in PostgreSQL?",
      "back": "To identify and optimize slow-running queries by analyzing execution plans (EXPLAIN ANALYZE), ensuring proper indexing, and reducing I/O overhead to improve overall database throughput and latency.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "How do you ensure transactional correctness in a distributed system using PostgreSQL?",
      "back": "By leveraging ACID properties, specifically using appropriate isolation levels (like Serializable or Repeatable Read), utilizing explicit transactions (BEGIN/COMMIT), and implementing optimistic or pessimistic locking strategies to prevent race conditions.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "What are the key benefits of gRPC over REST for internal service communication?",
      "back": "gRPC uses Protocol Buffers for efficient binary serialization, supports bi-directional streaming, offers strongly typed contracts, and provides better performance due to HTTP/2 multiplexing compared to JSON-based REST.",
      "requirement_ids": ["r4"]
    },
    {
      "front": "How do you handle breaking changes in a public-facing API?",
      "back": "Use versioning (e.g., /v1/, /v2/), support multiple versions concurrently during a deprecation period, and communicate changes clearly to consumers via changelogs and deprecation headers before removing old endpoints.",
      "requirement_ids": ["r4"]
    },
    {
      "front": "What is the most effective way to mentor a junior engineer?",
      "back": "Focus on 'show, don't tell' by pairing on complex tasks, encouraging them to own small features end-to-end, providing constructive code review feedback, and asking guiding questions rather than giving direct answers.",
      "requirement_ids": ["r5"]
    },
    {
      "front": "What is the 'on-call' philosophy for a Senior Backend Engineer?",
      "back": "You build it, you run it. On-call is about ownership: proactively monitoring services, creating actionable alerts, maintaining runbooks, and performing post-mortems to prevent recurring incidents.",
      "requirement_ids": ["r6"]
    },
    {
      "front": "What is the purpose of Terraform in infrastructure management?",
      "back": "Terraform is an Infrastructure as Code (IaC) tool that allows you to define, provision, and manage cloud infrastructure using declarative configuration files, ensuring environment consistency and reproducibility.",
      "requirement_ids": ["r7"]
    },
    {
      "front": "What is a common challenge when scaling event streaming systems like Kafka?",
      "back": "Managing partition rebalancing, handling consumer group lag, ensuring message ordering guarantees, and managing data retention policies while maintaining high availability and throughput.",
      "requirement_ids": ["r9"]
    },
    {
      "front": "Explain the difference between Node.js and Go concurrency models.",
      "back": "Node.js uses a single-threaded event loop with non-blocking I/O and callbacks/promises. Go uses goroutines (lightweight threads) and channels for CSP-style (Communicating Sequential Processes) concurrency, allowing for easier parallel execution.",
      "requirement_ids": ["r2"]
    },
    {
      "front": "What is the 'Outbox Pattern' in microservices?",
      "back": "A pattern to ensure transactional consistency between a database update and an event emission. You write the event to an 'outbox' table in the same transaction as your business data, then a separate process relays it to the message broker.",
      "requirement_ids": ["r3", "r9"]
    },
    {
      "front": "How do you manage database migrations in production?",
      "back": "Use versioned migration scripts, ensure they are idempotent, run them as part of the deployment pipeline, and always design them to be backward compatible so the application can roll back without breaking the schema.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "What is the main advantage of Kubernetes for backend services?",
      "back": "It provides automated container orchestration, including self-healing (restarting failed containers), horizontal scaling, service discovery, load balancing, and rolling updates, simplifying the management of complex distributed systems.",
      "requirement_ids": ["r7"]
    },
    {
      "front": "What is a critical consideration in supply chain software architecture?",
      "back": "Handling high-volume, asynchronous state changes (e.g., inventory updates, shipping status) while maintaining strict data integrity and ensuring the system can handle eventual consistency across distributed warehouses or partners.",
      "requirement_ids": ["r8"]
    },
    {
      "front": "How do you approach technical debt in a long-running production service?",
      "back": "Identify debt that blocks feature velocity or causes stability issues, quantify the impact, prioritize it alongside new features in the roadmap, and incrementally refactor rather than attempting massive rewrites.",
      "requirement_ids": ["r1"]
    }
  ]
}
